CREATE TABLE `exchange_rate` (
	`id` text PRIMARY KEY NOT NULL,
	`date` text NOT NULL,
	`usd_rate` real NOT NULL,
	`eur_rate` real NOT NULL,
	`source` text DEFAULT 'bcv' NOT NULL,
	`raw_usd` text NOT NULL,
	`raw_eur` text NOT NULL,
	`scraped_at` integer NOT NULL,
	`created_at` integer DEFAULT (cast(unixepoch('subsecond') * 1000 as integer)) NOT NULL,
	`updated_at` integer DEFAULT (cast(unixepoch('subsecond') * 1000 as integer)) NOT NULL
);
--> statement-breakpoint
CREATE UNIQUE INDEX `exchange_rate_source_date_unique` ON `exchange_rate` (`source`,`date`);--> statement-breakpoint
CREATE INDEX `exchange_rate_date_idx` ON `exchange_rate` (`date`);--> statement-breakpoint
